from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import SystemNotice, SecurityVulnerabilityNotice
from .serializers import SystemNoticeSerializer

class SystemNoticeDetailView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, notice_id):
        try:
            notice = SystemNotice.objects.get(id=notice_id)
        except SystemNotice.DoesNotExist:
            return Response({'error': 'Notice not found'}, status=status.HTTP_404_NOT_FOUND)

        if isinstance(notice, SecurityVulnerabilityNotice) and not request.user.is_security_team:
            return Response({'error': 'Security vulnerability advisories restricted to SOC members'}, status=status.HTTP_403_FORBIDDEN)

        return Response(SystemNoticeSerializer(notice).data)
